import{z as p,x as d,o as s,c as m,q as l,j as i,D as e,d as n,s as o,S as E,b as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"通用散列","description":"","frontmatter":{"title":"通用散列","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/universal-hashing.md","filePath":"cs/universal-hashing.md","lastUpdated":1791413859000}'),h={name:"cs/universal-hashing.md"};function A(B,a,C,c,u,f){const t=d("Mermaid");return s(),m("div",null,[a[2]||(a[2]=l('<h1 id="通用散列" tabindex="-1">通用散列 <a class="header-anchor" href="#通用散列" aria-label="Permalink to &quot;通用散列&quot;">​</a></h1><div class="epigraph"><p>函数从族里随机抽：任意一对不同键碰撞的概率 $\\le 1/m$；最坏输入对期望仍然成立。</p><footer>—— 据 Carter and Wegman, Universal Classes of Hash Functions, JCSS 1979；Cormen, Leiserson, Rivest and Stein 第 11 章整理</footer></div><p><a href="/cs/art-adaptive-radix">上一课</a> 结束字符串结构。主干<a href="/cs/hash-collision">散列碰撞</a> 已说明固定 \\(h\\) 可被对抗。<a href="/cs/string-hashing">字符串哈希</a> 用了随机模，未给族的定义。本课不画 ART 节点。缺口是 Carter–Wegman 通用散列：期望分析的合法前提。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>链地址、布隆、草图都要「碰撞不多」。对手若知道 \\(h\\)，可构造全撞一槽。通用族 \\(\\mathcal{H}\\)：对任意 \\(x\\neq y\\)，</p> \\[\\Pr_{h\\in\\mathcal{H}}[h(x)=h(y)] \\le 1/m \\]<p>（\\(m\\) 为槽数）。强通用（pairwise independent）还要求任意两槽对均匀。缺口是<strong>把随机性放在选 \\(h\\)，而不是假设输入随机</strong>。</p><p><span class="marginnote">Carter and Wegman, <em>JCSS</em>, 1979。多项式、乘法散列 \\(h_a(x)=\\lfloor m(ax\\bmod 2^w)/2^{w}\\rfloor\\) 等是常见构造。CLRS 第 11 章。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实践：程序启动抽 \\(a,b\\)，线性 \\(((ax+b)\\bmod p)\\bmod m\\)。证明两键碰撞化为一次均匀。多重独立（\\(k\\)-wise）给更好尾界，Count-Min 后课用。本课只钉 pairwise 级。</p>',10)),(s(),i(E,null,{default:e(()=>[o(t,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADV%5B%22%E4%BB%BB%E6%84%8F%E5%9B%BA%E5%AE%9A%20x%20%E2%89%A0%20y%22%5D%20--%3E%20H%5B%22%E9%9A%8F%E6%9C%BA%20h%20%E2%88%88%20H%22%5D%0A%20%20H%20--%3E%20COL%5B%22P(%E7%A2%B0%E6%92%9E)%20%E2%89%A4%201%2Fm%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,"与密码学哈希：通用散列不要求原像困难，只要碰撞概率；更快、键更短。不要混用 SHA 当布隆的 \\(k\\) 个索引——可以，但过重。",-1)),a[4]||(a[4]=r("h2",{id:"机制",tabindex:"-1"},[n("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=r("p",null,"一次完整的线性通用散列计算，以及碰撞过多时的换族流程：",-1)),(s(),i(E,null,{default:e(()=>[o(t,{id:"mermaid-36",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E8%BE%93%E5%85%A5%E9%94%AE%20x%22%5D%20--%3E%20M1%5B%22y1%20%3D%20a%C2%B7x%20%2B%20b%22%5D%0A%20%20M1%20--%3E%20M2%5B%22y2%20%3D%20y1%20mod%20p%20(p%20%E4%B8%BA%E5%A4%A7%E7%B4%A0%E6%95%B0)%22%5D%0A%20%20M2%20--%3E%20M3%5B%22slot%20%3D%20y2%20mod%20m%22%5D%0A%20%20M3%20--%3E%20INS%5B%22%E6%8F%92%E5%85%A5%E6%A7%BD%20slot%22%5D%0A%20%20INS%20--%3E%20CHK%7B%22%E9%93%BE%E9%95%BF%E8%B6%85%E5%87%BA%E9%98%88%E5%80%BC%3F%22%7D%0A%20%20CHK%20--%3E%7C%E5%90%A6%7C%20OK%5B%22%E7%85%A7%E5%B8%B8%E8%BF%90%E8%A1%8C%22%5D%0A%20%20CHK%20--%3E%7C%E6%98%AF%7C%20RE%5B%22%E6%8D%A2%E6%97%8F%3A%20%E9%87%8D%E6%8A%BD%E6%96%B0%20(a%2C%20b)%22%5D%0A%20%20RE%20--%3E%20REB%5B%22%E5%85%A8%E8%A1%A8%E6%8C%89%E6%96%B0%20h%20%E9%87%8D%E6%95%A3%E5%88%97%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p>期望链长：对固定键集，期望 \\(\\alpha\\) 与简单均匀假设相同，但现在对对抗输入也成立（期望对 \\(h\\)）。再散列换 \\(h\\) 即换族中另一员。实现须真随机种子，不能写死 \\(a=31\\)。</p><p><span class="marginnote">通用族可以翻译成「保险单」：这一篮子函数里没有哪个单独靠谱，但任意一对键撞进同一槽的概率都被保险到 \\(\\le 1/m\\)。\\(m=1000\\) 个槽时，无论对手挑什么键对，碰撞概率都不超过千分之一——概率论从「假设输入随机」换成「假设我抽函数随机」。</span></p><p><span class="marginnote">常见误区：以为写死 \\(a=31\\)、\\(b=0\\) 的经典字符串哈希也算通用散列。族是集合，抽签才给界；写死等于把唯一的骰子钉在桌面上，对手照样能构造全撞一槽的键集。素数 \\(p\\) 也别随手取，常用 \\(2^{61}-1\\) 这类梅森素数。</span></p><p><span class="marginnote">「重抽 \\((a,b)\\)」是最后手段：换一个 \\(h\\) 等于换族里另一名成员，此前的坏运气不继承。代价是全表重建一次，所以工程上只在负载因子失控或链长统计显著超标时触发。</span></p><p>完美散列下一课在通用之上再消除碰撞（静态）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把有限域全部构造写完。一致性哈希解决的是槽增减，不是碰撞界。</p><p>后课默认：字典分析用通用族。静态零碰撞用完美散列。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>通用族：任意一对碰撞概率 \\(\\le 1/m\\)。</li><li>随机在函数，不在数据。</li><li>静态无碰撞字典是完美散列。</li><li>出处：Carter and Wegman, <em>JCSS</em>, 1979；Cormen et al.。</li></ul>',10))])}const b=p(h,[["render",A]]);export{_ as __pageData,b as default};
